package com.bank.ec2;

import java.util.logging.*;

public class Ec2LaunchDemo {
    private static final Logger log = Logger.getLogger("EC2");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        InstanceTypeAdvisor advisor = new InstanceTypeAdvisor();
        String fraudType = advisor.recommend("cpu-heavy");     // fraud scoring
        String cacheType = advisor.recommend("memory-heavy");  // market-data cache
        log.info(() -> "Fraud scoring recommended type: " + fraudType);
        log.info(() -> "Market-data cache recommended type: " + cacheType);

        LaunchSpec spec = new LaunchSpec("ami-0abcd1234", fraudType,
                "nbi-settlement-key", "sg-0settlement", "subnet-0private-a",
                "SettlementReaderProfile", 50);

        InstanceLauncher launcher = new InstanceLauncher();
        String id = launcher.launch(spec);
        log.info(() -> "Launched instance " + id + " with spec " + spec);
    }
}

// ─── Would be in LaunchSpec.java ───
class LaunchSpec {
    final String ami, instanceType, keyPair, securityGroup, subnet, iamProfile;
    final int rootVolumeGb;
    LaunchSpec(String ami, String type, String key, String sg, String subnet,
               String profile, int rootGb) {
        this.ami = ami; this.instanceType = type; this.keyPair = key;
        this.securityGroup = sg; this.subnet = subnet; this.iamProfile = profile;
        this.rootVolumeGb = rootGb;
    }
    @Override public String toString() {
        return instanceType + " in " + subnet + " role=" + iamProfile + " disk=" + rootVolumeGb + "GB";
    }
}

// ─── Would be in InstanceTypeAdvisor.java ───
class InstanceTypeAdvisor {
    String recommend(String profile) {
        return switch (profile) {
            case "cpu-heavy"     -> "c6i.2xlarge";   // compute optimized
            case "memory-heavy"  -> "r6i.2xlarge";   // memory optimized
            case "storage-heavy" -> "i4i.xlarge";    // storage optimized
            default              -> "m6i.large";     // general purpose
        };
    }
}

// ─── Would be in InstanceLauncher.java ───
class InstanceLauncher {
    String launch(LaunchSpec s) {
        if (s.ami == null || s.ami.isBlank()) throw new IllegalArgumentException("AMI required");
        if (s.iamProfile == null) throw new IllegalArgumentException("IAM role required — never embed keys");
        if (s.securityGroup == null) throw new IllegalArgumentException("Security group required");
        return "i-" + Integer.toHexString(s.hashCode());  // would be ec2.runInstances()
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
